import{z as l,x as r,o as c,c as i,q as o,j as s,D as a,d as E,s as A,S as n}from"./chunks/framework.C8m1ZpeB.js";const I=JSON.parse('{"title":"TCP 状态机的实现","description":"","frontmatter":{"title":"TCP 状态机的实现","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/npk-tcp-state-machine.md","filePath":"cs/npk-tcp-state-machine.md","lastUpdated":1791413859000}'),p={name:"cs/npk-tcp-state-machine.md"};function d(T,e,_,C,B,S){const t=r("Mermaid");return c(),i("div",null,[e[2]||(e[2]=o('<h1 id="tcp-状态机的实现" tabindex="-1">TCP 状态机的实现 <a class="header-anchor" href="#tcp-状态机的实现" aria-label="Permalink to &quot;TCP 状态机的实现&quot;">​</a></h1><div class="epigraph"><p>协议文档把状态画成一张图；实现里它是一个整型字段加上散落在各处理函数里的迁移代码——真正要读懂的是每条迁移边上谁改了它、谁在等它。</p><footer>—— 据 RFC 9293；Stevens, <em>TCP/IP Illustrated Vol. 2</em>；Linux net/ipv4 源码口径整理</footer></div><p><a href="/cs/npk-rx-path">上一课</a>把帧送进 sk 接收队列并唤醒读者，<code>tcp_v4_rcv</code> 在 established 表里按四元组找 sock——但只找了「已建立」的连接。主干课已用<a href="/cs/tcp-state-machine">TCP 状态机</a>钉死十一态的主路径与 <a href="/cs/tcp-time-wait">TIME_WAIT</a> 的理由，<a href="/cs/kernel-tcp-impl">内核 TCP 实现要点</a>点过队列与定时器的名。本课补实现这一层：状态存放在哪、迁移由谁执行、每一态的 sock 住在哪张表里。后课的拥塞变量、套接字层都建立在这份账上。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>状态机不难画，难的是它的实现形态决定资源账：LISTEN 的半开连接放哪个队列、满了谁被丢；TIME_WAIT 为什么不是 sock 而是另一个对象；close 返回之后连接归谁。不这么做会错在哪：把 TIME_WAIT 当泄漏全局关掉，旧段的序号会串进新连接——主干课的警告，其机制就是这里的状态对象生命周期；把 accept 队列满当成「客户端慢」，会去调对端超时，而病根在本机 <code>listen(fd, backlog)</code> 与 <code>somaxconn</code> 的配置；以为 <code>close()</code> 即刻回收，会在高连接周转时撞上孤儿连接的内存上限——内核可能替你提前发 RST。</p><p><span class="marginnote">直觉类比：LISTEN 的两个队列像银行大厅——SYN 队列是「取号区」（来人领号，还没办业务），accept 队列是「叫到号、在柜台等签字的窗口席」（三次握手完成，等 <code>accept()</code> 这个柜员来接待）。取号区爆满是攻击洪泛，窗口席爆满是柜员（应用）叫号太慢——病灶不同，药方也不同。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按状态对象读。LISTEN 态：监听 sock 挂两个队列——SYN 队列放半开连接（收到 SYN、回完 SYN-ACK、等第三次握手的 <code>request_sock</code>），accept 队列放三次握手完成、等 <code>accept()</code> 领走的子连接；accept 队列满则丢第三次握手 ACK（对端重传），<code>tcp_syncookies</code> 打开时改用无状态的 cookie 应答，把半开状态搬进序号里（<a href="/cs/syn-cookies">SYN cookies</a>）。ESTABLISHED 态：完整 sock 挂四元组哈希表，<a href="/cs/npk-rx-path">上一课</a>的查找命中就是这张表。TIME_WAIT 态：tw_sock 是缩小版对象，不占发送队列与拥塞状态，进独立的 timewait 表，受 <code>tcp_max_tw_buckets</code>（默认 262144）封顶，超限按最旧淘汰；<code>tcp_tw_reuse</code> 只对主动发起方生效。关闭路径：主动关走 FIN-WAIT 到 TIME_WAIT；close 时应用不再持有但连接未关完，sock 变成孤儿（orphan），计入全机 <code>tcp_max_orphans</code>，内存压力下内核直接 RST 回收。有未读数据的连接 close 会发 RST——数据还没给应用，可靠的语义已经不成立。</p>',8)),(c(),s(n,null,{default:a(()=>[A(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20LI%5B%22LISTEN%EF%BC%9ASYN%20%E9%98%9F%E5%88%97%20%2B%20accept%20%E9%98%9F%E5%88%97%22%5D%20--%3E%7C%22%E6%8F%A1%E6%89%8B%E5%AE%8C%E6%88%90%22%7C%20ES%5B%22ESTABLISHED%EF%BC%9A%E5%9B%9B%E5%85%83%E7%BB%84%E5%93%88%E5%B8%8C%E8%A1%A8%22%5D%0A%20%20ES%20--%3E%7C%22%E4%B8%BB%E5%8A%A8%E5%85%B3%22%7C%20FW%5B%22FIN-WAIT%EF%BC%9A%E4%BB%8D%E6%98%AF%E5%AE%8C%E6%95%B4%20sock%22%5D%0A%20%20FW%20--%3E%20TW%5B%22TIME_WAIT%EF%BC%9Atw_sock%20%E5%B0%8F%E5%AF%B9%E8%B1%A1%22%5D%0A%20%20ES%20--%3E%7C%22close%20%E6%9C%AA%E5%85%B3%E5%AE%8C%22%7C%20OR%5B%22orphan%20%E9%98%9F%E5%88%97%EF%BC%9A%E5%8F%97%E5%85%A8%E6%9C%BA%E4%B8%8A%E9%99%90%22%5D%0A%20%20OR%20--%3E%7C%22%E5%86%85%E5%AD%98%E5%8E%8B%E5%8A%9B%22%7C%20RST%5B%22RST%20%E5%9B%9E%E6%94%B6%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[E(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=o('<p><span class="marginnote">术语翻译：SYN cookies 就是「把半开连接的档案折进序号本身」的手段来做「不占队列格子也能完成握手」的事——服务端不再记住你，而是把关键信息加密混在 SYN-ACK 的序号里，第三次握手的 ACK 带回来时再验算。代价是丢掉部分 TCP 选项的协商空间，所以它只该是洪泛时的应急档。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>实现形态解释了行为怪癖。同一逻辑连接在不同态住在不同的表里，查找方（上一课的收包路径）必须在每一态命中正确的表——这就是为什么 SYN-RECEIVED 的包要查两张表、TIME_WAIT 收到包可能回 ACK 也可能回 RST。迁移代码散在 ACK 与数据处理函数里而不是一张查找表，因为每条边还携带动作：发段、起定时器、清记账——图是抽象，边才是程序。定时器把「无包可等」的态挂上时钟：重传定时器、FIN-WAIT-2 的孤儿超时、保活定时器探半开连接，都是把状态机的停滞变成可回收事件。<code>SO_LINGER</code> 的 RST 档、带未读数据的 close，都是把优雅关换成中止态的出口。</p><p><span class="marginnote">accept 队列长度的真实上限是 <code>min(backlog, somaxconn)</code>，内核 5.4 起默认 4096，旧内核是 128——「改了应用 backlog 没用」先查它。<code>ss -lnt</code> 的 Recv-Q 在 LISTEN 态读出的正是当前 SYN 队列深度，是半开积压的直接观测。</span></p><p><span class="marginnote">数字实例：TIME_WAIT 停 60 秒，稳态数量约等于「每秒新建连接数 × 60」。每秒关 4000 条连接，稳态就压着 24 万个 tw_sock，已贴近默认上限 <code>tcp_max_tw_buckets</code> 262144——再多就开始淘汰最旧的，压测日志里的「连接被静默丢弃」常是这笔账，不是丢包。</span></p>',5)),(c(),s(n,null,{default:a(()=>[A(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20ES2%5B%22ESTABLISHED%22%5D%20--%3E%7C%22%E8%A2%AB%E5%8A%A8%E5%85%B3%3A%20%E5%AF%B9%E7%AB%AF%E5%85%88%20FIN%22%7C%20CW%5B%22CLOSE-WAIT%3A%20%E7%AD%89%E5%BA%94%E7%94%A8%20close%22%5D%0A%20%20CW%20--%3E%7C%22%E5%BA%94%E7%94%A8%E8%B0%83%20close%22%7C%20LA%5B%22LAST-ACK%3A%20%E5%8F%91%E8%87%AA%E5%B7%B1%E7%9A%84%20FIN%22%5D%0A%20%20LA%20--%3E%7C%22%E6%94%B6%E5%88%B0%20ACK%22%7C%20CL%5B%22CLOSED%22%5D%0A%20%20CW%20--%3E%7C%22%E5%BA%94%E7%94%A8%E6%8B%96%E7%9D%80%E4%B8%8D%20close%22%7C%20HANG%5B%22%E8%BF%9E%E6%8E%A5%E6%8C%82%E5%9C%A8%20CLOSE-WAIT%2C%20%E5%86%85%E5%AD%98%E4%B8%8D%E8%BF%98%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[E(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=o('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重画<a href="/cs/tcp-state-machine">主干状态机</a>的十一态全图，不展开同时打开与同时关闭的边角，TFO 与 <a href="/cs/mptcp">MPTCP</a> 的多子流状态不在此。syncookies 只接主干结论：它换掉的是状态不是安全性。后课默认：cwnd 等拥塞变量栖在 ESTABLISHED 的 sock 上、随状态生灭；下一课把这些变量的更新时机拆开。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>状态机的实现 = 一个 state 字段、散装的迁移边、按态分家的数据结构。</li><li>LISTEN 有两队列：SYN 队列放半开，accept 队列放成品；满与洪泛各有对策。</li><li>TIME_WAIT 是 tw_sock 小对象，受全机桶数封顶；orphan 是无人认领的 sock，受内存上限。</li><li>close 不等于 CLOSED：带未读数据发 RST，关不完变孤儿。</li><li>出处：RFC 9293；Stevens, <em>TCP/IP Illustrated Vol. 2</em>；Linux net/ipv4 源码口径整理。</li></ul>',4))])}const m=l(p,[["render",d]]);export{I as __pageData,m as default};
